method strlen(string: string) returns (length: int)
    requires string != null  // Precondition: string should not be null
    ensures length >= 0      // Postcondition: length is non-negative
    ensures length == |string| // Postcondition: length is equal to the length of the input string
{
    length := 0;
    var i := 0;
    while i < |string|
        invariant 0 <= i <= |string| // Invariant: i is within the bounds of the string
        invariant length == i         // Invariant: length matches the index i
    {
        length := length + 1;
        i := i + 1;
    }
}
```

